import asyncio, signal, os, threading, time
from run import run_tasks

cleanup_ran = []
def mk(i):
    async def t():
        try: await asyncio.sleep(10)
        except BaseException as e:
            print(f'{i} body {type(e).__name__}'); raise
        finally:
            print(f'{i} finally enter')
